; Sharp infrared frame pair with a 38 kHz carrier; one host word holds both 15-bit frames (the second inverted), acknowledged
; Generated by escgen from protocols/sharp_tx.yaml: edit the table and
; regenerate (python -m escgen), or take this file over by hand.
; Reference: SB-Projects, Sharp Protocol, www.sbprojects.net/knowledge/ir/sharp.php: 38 kHz carrier, 320 us bursts, 1 ms (0) and 2 ms (1) bit periods, 5 address bits, 8 command bits, expansion 1, check 0, LSB first; repeated 40 ms later with the command, expansion and check bits inverted
; Every edge is a DRIVE event at an absolute deadline; escert certifies it.

.default CTX, 0
.default CLK_KHZ, 25000                ; core clock in kHz
.equ PERIOD, (CLK_KHZ * 10 + 190) // 380
.equ NBIT, 12
.equ BIT0, CLK_KHZ
.equ BIT1, CLK_KHZ * 2
.equ GAP, CLK_KHZ * 40
.equ C_PERIOD, PERIOD
.equ C_HIGH, (PERIOD + 1) // 3
.default PIN_IR, 0
.equ P_IR, 1 << PIN_IR

.own  PIN_IR, CTX
.entry CTX, main

main:
    ADDT  16                          ; first deadline after the first commit
    EMIT  P_IR, 0, P_IR               ; idle levels
    ADDT  1
packet:
    POP   r1                          ; one word per packet (waits for the host)
    WAITT                             ; the last packet's final phase has ended
    RDTIME r3
    ADDI  r3, 64
    SETT  r3
    MOVI  r3, 15                      ; 15 bits, LSB first, each zero or one
bit1:
    SHR   r1, 1                       ; C = the next bit
    JC    one2
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    JMP   next3
one2:
    LDLC  (NBIT * PERIOD) // C_PERIOD ; one: carrier pulses
    CALL  burst
    ADDT  BIT1 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
next3:
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last bit
    JNZ   bit1
    LDLC  (NBIT * PERIOD) // C_PERIOD ; stop: carrier pulses
    CALL  burst
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 15                      ; 15 bits, LSB first, each zero or one
bit4:
    SHR   r1, 1                       ; C = the next bit
    JC    one5
    LDLC  (NBIT * PERIOD) // C_PERIOD ; zero: carrier pulses
    CALL  burst
    ADDT  BIT0 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    JMP   next6
one5:
    LDLC  (NBIT * PERIOD) // C_PERIOD ; one: carrier pulses
    CALL  burst
    ADDT  BIT1 - NBIT * PERIOD - 64   ; no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
next6:
    MOVI  r0, 1
    SUB   r3, r0                      ; Z after the last bit
    JNZ   bit4
    LDLC  (NBIT * PERIOD) // C_PERIOD ; stop: carrier pulses
    CALL  burst
    ADDT  GAP - 64                    ; gap: no change, no event; a long wait: let the queue drain
    WAITT
    ADDT  64
    MOVI  r3, 1
    PUSH  r3                          ; packet sent
    JMP   packet

; ---- burst: lc carrier pulses from tmr; returns with tmr = start + lc * C_PERIOD
burst:
    EMIT  P_IR, P_IR, P_IR
    ADDT  C_HIGH
    EMIT  P_IR, 0, P_IR
    ADDT  C_PERIOD - C_HIGH
    DJNZ  burst
    RET
